<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Boxes, Check, ImageOff, RefreshCw, Search, SlidersHorizontal } from 'lucide-vue-next'
import { productCatalogAPI, type ProductCatalogItem } from '@/api/productCatalog'
import { useAdminAuthStore } from '@/stores/auth'
import { getImageUrl } from '@/utils/image'

const auth = useAdminAuthStore()
const rows = ref<ProductCatalogItem[]>([])
const loading = ref(false)
const syncing = ref(false)
const error = ref('')
const notice = ref('')
const search = ref('')
const active = ref('all')
const page = ref(1)
const pageSize = 20
const total = ref(0)
const includeInactive = ref(true)
const editing = ref<number | null>(null)
const drafts = reactive<Record<number, { cost_price: string; sale_price: string; follow_product_price: boolean }>>({})
const editRow = ref<ProductCatalogItem | null>(null)

const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize)))
const title = (row: ProductCatalogItem) => row.title?.['zh-CN'] || Object.values(row.title || {}).find(Boolean) || row.product_slug || `商品 #${row.product_id}`
const money = (value: unknown) => { const n = Number(value); return Number.isFinite(n) ? n.toFixed(2) : '0.00' }
const image = (row: ProductCatalogItem) => getImageUrl(row.images?.[0])
const statusText = (row: ProductCatalogItem) => row.product_active && row.sku_active ? '在售' : '已下架'
const statusClass = (row: ProductCatalogItem) => row.product_active && row.sku_active ? 'is-active' : 'is-inactive'
const specText = (row: ProductCatalogItem) => Object.values(row.spec_values || {}).filter(Boolean).join(' / ')
const inventoryText = (row: ProductCatalogItem) => row.inventory < 0 ? '不限库存' : String(row.inventory)
function normalizeRow(value: any): ProductCatalogItem { return value?.item ? { ...value.item, ...value } : value }
async function load() { loading.value = true; error.value = ''; try { const response = await productCatalogAPI.list({ page: page.value, page_size: pageSize, search: search.value.trim(), product_active: active.value }); rows.value = (response.data.data || []).map(normalizeRow); total.value = Number(response.data.pagination?.total || 0) } catch (e: any) { error.value = e?.message || '加载商品清单失败' } finally { loading.value = false } }
async function searchRows() { page.value = 1; await load() }
async function syncCatalog() { if (!auth.isSuper || syncing.value) return; syncing.value = true; error.value = ''; notice.value = ''; try { await productCatalogAPI.sync(includeInactive.value); notice.value = includeInactive.value ? '已同步主站在售及已下架商品，手工成本和售价保持不变。' : '已同步主站在售商品。'; await load() } catch (e: any) { error.value = e?.message || '同步商品清单失败' } finally { syncing.value = false } }
function startEdit(row: ProductCatalogItem) { editRow.value = row; editing.value = row.id; drafts[row.id] = { cost_price: String(row.cost_price ?? ''), sale_price: String(row.sale_price ?? ''), follow_product_price: Boolean(row.follow_product_price) } }
function cancelEdit() { editing.value = null; editRow.value = null }
async function save(row: ProductCatalogItem) { const draft = drafts[row.id]; if (!draft || loading.value) return; loading.value = true; error.value = ''; try { await productCatalogAPI.update(row.id, { cost_price: String(draft.cost_price ?? ''), sale_price: String(draft.sale_price ?? ''), follow_product_price: draft.follow_product_price }); editing.value = null; editRow.value = null; notice.value = `已保存「${title(row)}」的单个 SKU 设置。`; await load() } catch (e: any) { error.value = e?.message || '保存商品设置失败' } finally { loading.value = false } }
onMounted(load)
</script>

<template>
  <section class="catalog-page">
    <header class="page-header"><div class="heading-row"><div class="heading-icon"><Boxes class="size-5" /></div><div><h1>商品清单</h1><p>以主站商品和 SKU 为准，统一查看上下架状态、图片、售价、成本、利润与库存。</p></div></div><div v-if="auth.isSuper" class="sync-card"><div class="sync-copy"><strong>同步主站商品</strong><span>同步会更新名称、图片、SKU、状态、当前售价和库存，不会覆盖手工成本与售价。</span></div><label class="switch-label"><input v-model="includeInactive" type="checkbox" /> 包含已下架</label><button class="primary-button" :disabled="syncing" @click="syncCatalog"><RefreshCw class="size-4" :class="{ spin: syncing }" />{{ syncing ? '同步中…' : '同步商品' }}</button></div></header>
    <div v-if="error" class="alert error">{{ error }}</div><div v-if="notice" class="alert success"><Check class="size-4" />{{ notice }}</div>
    <section class="toolbar-card"><div class="search-box"><Search class="size-4" /><input v-model="search" placeholder="搜索商品名称、Slug 或 SKU" @keyup.enter="searchRows" /></div><select v-model="active" @change="searchRows"><option value="all">全部状态</option><option value="1">仅在售</option><option value="0">仅已下架</option></select><button class="secondary-button" :disabled="loading" @click="searchRows"><Search class="size-4" />查询</button><span class="result-count">共 {{ total }} 个 SKU</span></section>
    <section class="table-card"><div class="table-title"><div><h2>SKU 清单</h2><p>每一行都是独立 SKU，可单独设置跟随价格或手工售价。</p></div><SlidersHorizontal class="size-5 text-muted-foreground" /></div><div class="table-wrap"><table><thead><tr><th class="product-col">商品 / SKU</th><th>状态</th><th>主站售价</th><th>成本</th><th>清单售价</th><th>利润</th><th>利润率</th><th>库存</th><th class="action-col">操作</th></tr></thead><tbody><tr v-if="!loading && rows.length === 0"><td colspan="9" class="empty-cell">暂无商品，请先同步主站商品。</td></tr><tr v-for="row in rows" :key="row.id"><td class="product-cell"><div class="product-main"><div class="product-image"><img v-if="image(row)" :src="image(row)" :alt="title(row)" /><ImageOff v-else class="size-5" /></div><div class="product-copy"><strong>{{ title(row) }}</strong><span>{{ row.sku_code || '默认 SKU' }}<template v-if="specText(row)"> · {{ specText(row) }}</template></span><small>{{ row.product_slug }}</small></div></div></td><td><span class="status-pill" :class="statusClass(row)"><i />{{ statusText(row) }}</span></td><td class="amount">{{ money(row.product_price) }}</td><td class="amount">{{ money(row.cost_price) }}</td><td class="amount strong">{{ money(row.effective_sale_price) }}</td><td class="amount profit">{{ money(row.profit_amount) }}</td><td><span class="rate">{{ Number(row.profit_rate || 0).toFixed(2) }}%</span></td><td><span class="stock">{{ inventoryText(row) }}</span></td><td class="actions"><button v-if="auth.isSuper" class="secondary-button compact" @click="startEdit(row)">单独编辑</button><span v-else class="readonly">只读</span></td></tr></tbody></table></div><div class="pagination"><button class="secondary-button" :disabled="page <= 1 || loading" @click="page--; load()">上一页</button><span>第 {{ page }} / {{ totalPages }} 页</span><button class="secondary-button" :disabled="page >= totalPages || loading" @click="page++; load()">下一页</button></div></section>
    <div v-if="editRow" class="modal-backdrop" @click.self="cancelEdit"><section class="modal-card edit-modal"><div class="modal-header"><div><span class="eyebrow">SKU 价格设置</span><h2>{{ title(editRow) }}</h2><p class="muted">{{ editRow.sku_code || '默认 SKU' }} · {{ editRow.product_slug }}</p></div><button class="icon-button" @click="cancelEdit">×</button></div><div class="edit-grid"><label>成本价<input v-model="drafts[editRow.id]!.cost_price" type="number" min="0" step="0.01" /></label><label>手工售价<input v-model="drafts[editRow.id]!.sale_price" type="number" min="0" step="0.01" :disabled="drafts[editRow.id]!.follow_product_price" /></label></div><label class="follow-label modal-follow"><input v-model="drafts[editRow.id]!.follow_product_price" type="checkbox" /> 跟随主站商品价</label><div class="modal-actions"><button class="secondary-button" :disabled="loading" @click="cancelEdit">取消</button><button class="primary-button" :disabled="loading" @click="save(editRow)">{{ loading ? '保存中…' : '保存设置' }}</button></div></section></div>
  </section>
</template>

<style scoped>
.catalog-page{display:grid;gap:18px;max-width:1560px;margin:0 auto;min-width:0;color:hsl(var(--foreground))}.page-header{display:grid;gap:16px}.heading-row{display:flex;gap:13px;align-items:flex-start}.heading-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#0f766e;color:white;box-shadow:0 8px 18px #0f766e2e}.page-header h1{font-size:27px;font-weight:750;letter-spacing:-.02em}.page-header p,.table-title p{margin-top:4px;color:hsl(var(--muted-foreground));font-size:13px;line-height:1.6}.sync-card,.toolbar-card,.table-card{border:1px solid hsl(var(--border));border-radius:16px;background:hsl(var(--card));box-shadow:0 8px 24px #0f172a0a}.sync-card{display:flex;align-items:center;gap:18px;padding:14px 16px}.sync-copy{display:grid;gap:3px;flex:1}.sync-copy span{font-size:12px;color:hsl(var(--muted-foreground))}.switch-label,.follow-label{display:flex;align-items:center;gap:6px;font-size:12px;white-space:nowrap}.toolbar-card{display:flex;align-items:center;gap:10px;padding:12px;flex-wrap:wrap}.search-box{display:flex;align-items:center;gap:8px;min-width:260px;flex:1;border:1px solid hsl(var(--border));border-radius:10px;padding:0 11px;height:38px}.search-box input{border:0;outline:0;background:transparent;min-width:0;width:100%;font:inherit}.toolbar-card select,.inline-input{height:38px;border:1px solid hsl(var(--border));border-radius:10px;background:hsl(var(--background));padding:0 10px;color:inherit;font:inherit}.result-count{margin-left:auto;color:hsl(var(--muted-foreground));font-size:12px}.primary-button,.secondary-button,.link-button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border-radius:9px;padding:8px 12px;border:1px solid hsl(var(--border));font:inherit;font-size:13px;cursor:pointer;white-space:nowrap}.primary-button{background:#0f766e;color:white;border-color:#0f766e}.secondary-button{background:hsl(var(--background));color:inherit}.link-button{border-color:transparent;background:transparent;color:#0f766e}.primary-button:hover:not(:disabled){background:#115e59}.secondary-button:hover:not(:disabled){background:hsl(var(--muted))}.primary-button:disabled,.secondary-button:disabled,.link-button:disabled{opacity:.5;cursor:default}.compact{padding:6px 9px;font-size:12px}.alert{display:flex;align-items:center;gap:8px;border-radius:10px;padding:10px 13px;font-size:13px}.alert.error{color:#b42318;background:#fff1f0;border:1px solid #fecaca}.alert.success{color:#166534;background:#f0fdf4;border:1px solid #bbf7d0}.table-card{overflow:hidden}.table-title{display:flex;align-items:center;justify-content:space-between;padding:17px 18px;border-bottom:1px solid hsl(var(--border))}.table-title h2{font-size:16px;font-weight:700}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:separate;border-spacing:0;min-width:1120px;font-size:13px}th,td{padding:13px 12px;border-bottom:1px solid hsl(var(--border));text-align:left;vertical-align:middle}th{color:hsl(var(--muted-foreground));font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;background:hsl(var(--muted)/.28)}tbody tr:hover{background:hsl(var(--muted)/.18)}tbody tr:last-child td{border-bottom:0}.product-col{min-width:330px}.product-cell{min-width:330px}.product-main{display:flex;align-items:center;gap:11px}.product-image{display:grid;place-items:center;width:44px;height:44px;overflow:hidden;flex:none;border:1px solid hsl(var(--border));border-radius:10px;background:hsl(var(--muted)/.35);color:hsl(var(--muted-foreground))}.product-image img{width:100%;height:100%;object-fit:cover}.product-copy{display:grid;gap:3px;min-width:0}.product-copy strong{font-size:13px;overflow:hidden;text-overflow:ellipsis;max-width:310px}.product-copy span,.product-copy small{color:hsl(var(--muted-foreground));font-size:11px;overflow:hidden;text-overflow:ellipsis;max-width:310px}.product-copy small{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.status-pill{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;font-size:11px;font-weight:600}.status-pill i{width:6px;height:6px;border-radius:50%;background:currentColor}.status-pill.is-active{color:#047857;background:#ecfdf5}.status-pill.is-inactive{color:#64748b;background:#f1f5f9}.amount{font-variant-numeric:tabular-nums;white-space:nowrap}.strong{font-weight:700}.profit{color:#047857;font-weight:650}.rate{color:#047857;font-variant-numeric:tabular-nums}.stock{font-size:12px;white-space:nowrap}.inline-input{width:112px;padding:0 8px}.actions{min-width:190px}.readonly{color:hsl(var(--muted-foreground));font-size:12px}.follow-label{margin-bottom:7px}.empty-cell{text-align:center;padding:60px 20px;color:hsl(var(--muted-foreground))}.pagination{display:flex;align-items:center;gap:10px;justify-content:flex-end;padding:14px 18px;border-top:1px solid hsl(var(--border));font-size:12px;color:hsl(var(--muted-foreground))}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
.modal-backdrop{position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:20px;background:rgb(15 23 42 / .44);backdrop-filter:blur(3px)}.modal-card{width:min(100%,560px);border:1px solid hsl(var(--border));border-radius:18px;background:hsl(var(--card));box-shadow:0 24px 80px rgb(15 23 42 / .28);padding:22px}.modal-header{display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid hsl(var(--border));padding-bottom:14px}.modal-header h2{margin-top:4px;font-size:20px}.eyebrow{color:#0f766e;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.icon-button{width:32px;height:32px;padding:0;border-radius:9px;font-size:22px}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px 0 12px}.edit-grid label{display:grid;gap:7px}.edit-grid input{width:100%}.modal-follow{margin-bottom:20px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;border-top:1px solid hsl(var(--border));padding-top:15px}
@media (max-width:720px){.sync-card{align-items:flex-start;flex-direction:column}.result-count{margin-left:0}.toolbar-card{align-items:stretch}.search-box{min-width:100%}.toolbar-card select,.toolbar-card button{flex:1}.page-header h1{font-size:23px}}
</style>
